/**
 * Historical city-plan registry.
 *
 * Actual contemporary town plans take priority over illustrative procedural
 * blocks. WIG military sheets are clearly flagged as *regional* charts, never
 * presented as surveyed city blocks. An absent source is not invented.
 * All URLs are public provenance references; the optional local thumbnails
 * are generated by scripts/fetch-city-plans.py.
 */
import {ARCHIVE,archiveUrl,archiveFallbackUrl,regionalArchive} from "./archival-atlas-data.js";

const commons = file => "https://commons.wikimedia.org/wiki/File:"+encodeURIComponent(file);
const city = (title,year,file,local,notes,source=commons(file))=>({
 kind:"city",title,year,file,local,source,notes,license:"Public domain (see source record)"
});
export const CITY_PLANS = Object.freeze({
 warszawskie:city(
  "Plan miasta stołecznego Warszawy",1935,"Warszawa 1935.png","assets/maps/warszawa-1935.png",
  "1935 belediye sokak planı, 1:20.000. 1939 sonrasındaki yıkımı göstermez."),
 lodzkie:city(
  "Plan wojewódzkiego miasta Łodzi",1938,"Plan wojewodzkiego miasta Lodzi. ca 1938 (35842453).jpg","assets/maps/lodz-1938.jpg",
  "Yaklaşık 1938 tarihli gerçek cadde/sokak planı, 1:20.000."),
 slaskie:city(
  "Plan przewodnik na miasto Katowice",1939,"Plan przewodnik na miasto Katowice 1939 (1430909).jpg","assets/maps/city-katowice-1939.jpg",
  "1939 tarihli rehberin özgün kent planı."),
 lwowskie:city(
  "Horbaya, Plan orientacyjny Wielkiego Lwowa",1938,"Horbaya Plan orientacyjny Wielkiego Lwowa. 1938.jpg","assets/maps/city-lwow-1938.jpg",
  "1938 tarihli tarihî yön bulma planı. Kaynak görsel düşük çözünürlüklü."),
 pomorskie:city(
  "Plan Torunia",1921,"Map of Torun 1921.jpg","assets/maps/city-torun-1921.jpg",
  "1921 tarihli gerçek şehir planı; 1940'a kadar gerçekleşen değişiklikleri içermez.")
});

export const HISTORICAL_CITY_REFERENCES=Object.freeze({
 krakowskie:{title:"Plan miasta Krakowa",year:1938,source:"https://dawnemapykrakowa.pl/map/1938-plan-miasta-krakowa/",notes:"1:10.000, Adam Launer. Dijital kopyanın yeniden kullanım hakkı doğrulanmadığı için doğrudan aktarılmadı."},
 wilenskie:{title:"Plan miasta Wilna",year:1937,source:"https://pbc.biaman.pl/dlibra/publication/12353/edition/11784",notes:"1:12.500 özgün plan; PDF nüshası mevcut. Oyun içine yeniden işlenmiş dosya henüz eklenmedi."},
 bialostockie:{title:"Program ogólny zabudowania miasta Białegostoku",year:1939,source:"https://commons.wikimedia.org/wiki/File:Bia%C5%82ystok_general_city_plan_1939_01.jpg",notes:"1938–39 şehircilik TASARISI; gerçekleşmiş sokak ve yapılarla karıştırılmamalıdır."},
 wolynskie:{title:"Plan miasta Łucka, projekt ogólny zabudowania",year:1937,source:"https://jbc.bj.uj.edu.pl/Content/369036/PDF/NDIGCZAS016782_1937_008_009.pdf",notes:"1:5.000 imar tasarısı; önerilen yolların mevcut sokak sayılması doğru olmaz."}
});

/** Exclude sheets whose centre is elsewhere (e.g. Pińsk ≠ Brześć). */
export const VERIFIED_SHEET_REGIONS = Object.freeze([
 "poznanskie","kieleckie","krakowskie","lubelskie",
 "bialostockie","nowogrodzkie","wilenskie","wolynskie","stanislawowskie"
]);

export function cityMapRecord(region){
 const town = CITY_PLANS[region];
 if(town)return town;
 const row=VERIFIED_SHEET_REGIONS.includes(region)?regionalArchive(region):null;
 if(row){
  return {
   kind:"regional",year:row.year,title:row.title,file:row.file,
   local:archiveUrl(row.file),source:row.source,
   fallback:archiveFallbackUrl(row.file),
   license:"Public domain (source sheet)",
   notes:"WIG bölgesel askerî haritası, 1:300.000. Gerçek dönem coğrafyasıdır; bina veya şehir sokak planı değildir."
  };
 }
 return {
  kind:"unavailable",year:null,title:"Doğrulanmış dönem şehir planı yok",
  file:null,local:null,source:null,
  notes:"Bu kent için tarihsel sokak ağı doğrulanmadı. Gerçekmiş gibi rastgele sokaklar veya bina poligonları üretilmez."
 };
}

export function cityMapUrl(region){
 const data=cityMapRecord(region);
 return data.local||null;
}
export function cityMapFallback(region){
 const data=cityMapRecord(region);
 if(!data.file)return null;
 return data.fallback||archiveFallbackUrl(data.file);
}
